'use strict';
const L=window.Ledger;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',chart:'<path d="M4 3v17h17M8 15v-4m5 4V7m5 8V4"/>',wallet:'<path d="M20 8H5a2 2 0 0 1 0-4h13v4M3 6v13a1 1 0 0 0 1 1h16V8M20 12h-5v4h5"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6L12 3Z"/><path d="m8 11 3 3 5-5"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 4 16 4 16 0V5M4 12v7c0 4 16 4 16 0v-7"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',chevronDown:'<path d="m6 9 6 6 6-6"/>',chevronLeft:'<path d="m14 6-6 6 6 6"/>',chevronRight:'<path d="m10 6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrowRight:'<path d="M4 12h16m-6-6 6 6-6 6"/>',arrowUp:'<path d="M7 17 17 7M7 7h10v10"/>',arrowDown:'<path d="m7 7 10 10M7 17h10V7"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',sparkles:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4L12 3ZM20 2v4m-2-2h4"/>',leaf:'<path d="M20 3C10 3 3 5 3 12a7 7 0 0 0 7 7c7 0 10-7 10-16ZM3 21 15 9"/>',food:'<path d="M4 3v6c0 3 6 3 6 0V3M7 3v18M17 3c-4 4-4 10 1 10V3Zm1 10v8"/>',home:'<path d="m3 10 9-7 9 7M5 9v12h14V9M10 21v-7h4v7"/>',bag:'<path d="M5 7h14l2 14H3L5 7Zm3 0V6a4 4 0 0 1 8 0v1"/>',car:'<path d="m5 5-2 7v6h18v-6l-2-7H5ZM3 12h18M6 15h2m8 0h2M5 18v3m14-3v3"/>',film:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 3v18M17 3v18M3 8h4m-4 8h4M17 8h4m-4 8h4"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 4 1 10 8 15 7-5 12-11 8-15Z"/>',book:'<path d="M12 5v16M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Z"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12c6 4 12 4 18 0M12 11v5"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6Z"/>',trash:'<path d="M3 6h18M6 6l1 15h10l1-15M9 6V3h6v3M10 10v7m4-7v7"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',percent:'<path d="M5 19 19 5"/><circle cx="6.5" cy="6.5" r="2.5"/><circle cx="17.5" cy="17.5" r="2.5"/>',inbox:'<path d="m7 3-5 11v7h20v-7L17 3H7ZM2 14h6l2 3h4l2-3h6"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.wallet}</svg>`;}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.replaceWith(Object.assign(document.createElement('span'),{innerHTML:icon(el.dataset.icon)})));}
const fmt=n=>(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const compact=n=>(n/100).toLocaleString('zh-CN',{maximumFractionDigits:2});
const monthLabel=m=>`${m.slice(0,4)} 年 ${Number(m.slice(5))} 月`;
const STORAGE='moonledger.v1';
let storageProblem='';
let saved;
try{const raw=localStorage.getItem(STORAGE);if(raw){saved=JSON.parse(raw);if(![1,2].includes(saved.version))throw Error('版本不支持');saved.own=L.validateBook(saved.own);saved.demo=L.validateBook(saved.demo);}}catch(e){saved=undefined;storageProblem='本地账本无法读取，已暂停保存。请先导出原始数据，再恢复备份。';}
const state={mode:saved?.mode==='own'?'own':'demo',month:L.monthNow(),view:'overview',filter:'all',search:'',category:'all',page:1,own:saved?.own||{entries:[],budgets:{}},demo:saved?.demo||L.demoBook()};
if(storageProblem){state.own={entries:[],budgets:{}};state.demo=L.demoBook();}
const book=()=>state[state.mode];
function storedBooks(){const raw=localStorage.getItem(STORAGE);if(!raw)return {own:state.own,demo:state.demo};const parsed=JSON.parse(raw);if(![1,2].includes(parsed.version))throw Error('本地账本版本不支持，请先导出备份。');return {own:L.validateBook(parsed.own),demo:L.validateBook(parsed.demo)};}
function storageLock(action){if(!navigator.locks?.request)return Promise.reject(Error('当前浏览器不支持安全保存，请在新版 Chrome、Edge 或 Safari 中打开本地网址。'));return navigator.locks.request('moonledger:write',action);}
async function persist(){if(storageProblem){toast(storageProblem);return false;}try{return await storageLock(()=>{const latest=storedBooks();localStorage.setItem(STORAGE,JSON.stringify({version:2,mode:state.mode,...latest}));state.own=latest.own;state.demo=latest.demo;$('#save-status').textContent='已保存到当前浏览器';return true;});}catch(e){toast(e.message||'保存失败，请先导出备份。');return false;}}
async function commit(next,message,options={}){if(storageProblem){toast(storageProblem);return false;}const mode=state.mode,base=book();try{return await storageLock(()=>{const latest=options.recoverRaw!==undefined?(()=>{if(localStorage.getItem(STORAGE)!==options.recoverRaw)throw Error('原始数据已变化，请重新检查后恢复。');return {own:state.own,demo:state.demo};})():storedBooks();if(options.expectedEntry&&JSON.stringify(latest[mode].entries.find(e=>e.id===options.expectedEntry.id))!==JSON.stringify(options.expectedEntry))throw Error('这笔账单已在另一个页面修改或删除，请关闭表单并重新核对。');if(options.replace&&JSON.stringify(latest[mode])!==JSON.stringify(base))throw Error('账本已在其他页面更改，请重新核对后再替换或清空。');const merged=options.replace?L.validateBook(next):L.mergeChanges(base,next,latest[mode]);latest[mode]=merged;localStorage.setItem(STORAGE,JSON.stringify({version:2,mode:state.mode,...latest}));state.own=latest.own;state.demo=latest.demo;render();$('#save-status').textContent='已保存到当前浏览器';if(message)toast(message);return true;});}catch(e){toast(e.name==='QuotaExceededError'?'存储空间不足，请导出备份后整理账本。':e.message||'保存失败，请先导出备份。');return false;}}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function change(current,previous,lowerGood=false){if(!previous)return `<span class="stat-change">${current?'上月无记录':'暂无环比数据'}</span>`;const p=(current-previous)/Math.abs(previous)*100;const good=lowerGood?p<=0:p>=0;return `<span class="stat-change ${good?'good':'warn'}">${icon(p>=0?'arrowUp':'arrowDown')}${Math.abs(p).toFixed(1)}% <span style="color:inherit;opacity:.8">较上月</span></span>`;}
function spark(color,variant=0){return `<svg class="spark" viewBox="0 0 80 30" aria-hidden="true"><path d="${variant?'M1 20 13 17 25 23 37 9 49 12 61 5 79 8':'M1 25 12 23 22 25 32 12 43 17 54 7 66 13 79 2'}" fill="none" stroke="${color}" stroke-width="1.8"/></svg>`;}
function stats(){const s=L.summarize(book(),state.month),p=L.summarize(book(),L.shiftMonth(state.month,-1));return `<div class="stats-grid"><article class="stat-card featured"><div class="stat-top">本月结余 ${icon('wallet')}</div><div class="stat-amount"><span class="currency">¥</span>${fmt(s.balance)}</div><div class="stat-bottom">${change(s.balance,p.balance)}</div>${spark('#cde5a7')}</article><article class="stat-card"><div class="stat-top">本月收入 ${icon('arrowDown')}</div><div class="stat-amount"><span class="currency">¥</span>${fmt(s.income)}</div><div class="stat-bottom">${change(s.income,p.income)}</div>${spark('#98af79',1)}</article><article class="stat-card"><div class="stat-top">本月净支出 ${icon('arrowUp')}</div><div class="stat-amount"><span class="currency">¥</span>${fmt(s.expense)}</div><div class="stat-bottom">${change(s.expense,p.expense,true)}</div>${spark('#d4b292',1)}</article><article class="stat-card"><div class="stat-top">结余率 ${icon('percent')}</div><div class="stat-amount">${s.rate===null?'—':s.rate.toFixed(1)+'<span class="currency">%</span>'}</div><div class="stat-bottom">${s.income?'每一份收入，都有了去向':'记录收入后可计算结余率'}</div></article></div>`;}
function curve(points){return points.map((p,i)=>{if(!i)return `M${p[0]},${p[1]}`;const before=points[i-1],mid=(before[0]+p[0])/2;return `C${mid},${before[1]} ${mid},${p[1]} ${p[0]},${p[1]}`;}).join(' ');}
function trend(){const months=Array.from({length:6},(_,i)=>L.shiftMonth(state.month,i-5));const values=months.map(m=>L.summarize(book(),m));const max=Math.max(1000000,...values.flatMap(v=>[v.income,v.expense]));const floor=Math.floor(Math.min(0,...values.flatMap(v=>[v.income,v.expense]))/100000)*100000;const step=Math.ceil((max-floor)/4/100000)*100000;const ceiling=floor+step*4,baseline=21+ceiling/(ceiling-floor)*169;const points=key=>values.map((v,i)=>[47+i*99,21+(ceiling-v[key])/(ceiling-floor)*169]);const income=points('income'),expense=points('expense');const chart=values.some(v=>v.count)?`<svg viewBox="0 0 575 225" role="img" aria-label="最近六个月收入与支出趋势"><defs><linearGradient id="income-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#cadbb9" stop-opacity=".5"/><stop offset="1" stop-color="#eaf0e0" stop-opacity=".03"/></linearGradient><linearGradient id="expense-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#e1bc9a" stop-opacity=".17"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient></defs>${Array.from({length:5},(_,i)=>{const y=21+i*42.25;return `<line class="chart-grid" x1="47" y1="${y}" x2="553" y2="${y}"/><text class="chart-text" x="1" y="${y+4}">${ceiling-step*i>=1000000?((ceiling-step*i)/1000000).toFixed(1)+'万':compact(ceiling-step*i)}</text>`;}).join('')}<path d="${curve(income)} L542 ${baseline} L47 ${baseline} Z" fill="url(#income-fill)"/><path d="${curve(expense)} L542 ${baseline} L47 ${baseline} Z" fill="url(#expense-fill)"/><path d="${curve(income)}" fill="none" stroke="#829d63" stroke-width="2.5"/><path d="${curve(expense)}" fill="none" stroke="#d7ae88" stroke-width="2.3"/>${months.map((m,i)=>`<text class="chart-text" x="${47+i*99}" y="216" text-anchor="middle">${Number(m.slice(5))}月</text><circle cx="${income[i][0]}" cy="${income[i][1]}" r="${i===5?4:2.5}" fill="#829d63" stroke="#fff" stroke-width="1.5"><title>${monthLabel(m)} 收入 ¥${fmt(values[i].income)}</title></circle><circle cx="${expense[i][0]}" cy="${expense[i][1]}" r="${i===5?4:2.5}" fill="#d7ae88" stroke="#fff" stroke-width="1.5"><title>${monthLabel(m)} 支出 ¥${fmt(values[i].expense)}</title></circle>`).join('')}</svg>`:`<div class="empty-chart">记录第一笔，开始看见每个月的变化。</div>`;const total=values.reduce((a,v)=>a+v.balance,0);return `<section class="panel"><div class="panel-heading"><div><h2>收支趋势</h2><p class="panel-subtitle">${monthLabel(months[0])} — ${monthLabel(state.month)}</p></div><div class="legend"><span><i style="background:#829d63"></i>收入</span><span><i style="background:#d7ae88"></i>支出</span></div></div><div class="trend-chart">${chart}</div><div class="trend-foot">${icon('leaf')}近 6 个月累计${total<0?'超出收入':'结余'} <strong>¥${fmt(Math.abs(total))}</strong></div></section>`;}
function categoryChart(){const netItems=L.breakdown(book(),state.month),items=netItems.filter(c=>c.amount>0),adjustment=netItems.filter(c=>c.amount<0).reduce((s,c)=>s+c.amount,0),total=items.reduce((s,c)=>s+c.amount,0);let segments=items.slice(0,4);if(items.length>4)segments.push({name:'其他分类',amount:items.slice(4).reduce((a,c)=>a+c.amount,0),percent:items.slice(4).reduce((a,c)=>a+c.percent,0),color:'#ddd6bc'});let offset=0;const rings=segments.map(c=>{const length=c.percent*3.0159;const r=`<circle cx="90" cy="90" r="69" fill="none" stroke="${c.color}" stroke-width="22" stroke-dasharray="${Math.max(0,length-3)} ${433.54-Math.max(0,length-3)}" stroke-dashoffset="${-offset}" pathLength="301.59"><title>${c.name} ¥${fmt(c.amount)}</title></circle>`;offset+=length;return r;}).join('');return `<section class="panel"><div class="panel-heading"><div><h2>支出分类</h2><p class="panel-subtitle">${adjustment<0?'另有分类净冲减 ¥'+fmt(-adjustment)+'，未绘入环图':'退款与报销已按到账月冲减'}</p></div><button class="icon-button" data-action="analysis" aria-label="查看消费分析">${icon('arrowUp')}</button></div>${items.length?`<div class="category-body"><div class="donut-wrap"><svg viewBox="0 0 180 180" role="img" aria-label="支出分类占比">${rings}</svg><div class="donut-label"><small>分类正向净支出</small><strong>¥${compact(total)}</strong></div></div><div class="category-legend">${segments.map(c=>`<div class="category-legend-row"><i style="background:${c.color}"></i><span>${c.name}</span><strong>${c.percent.toFixed(1)}%</strong></div>`).join('')}</div></div>`:`<div class="empty-chart">本月没有正向净支出</div>`}<div class="category-foot"><span>${items.length?'最大的消费去向':'从小小的一笔开始'}</span><strong>${items.length?`${items[0].name} · ${items[0].percent.toFixed(0)}%`:'记录你的日常'}</strong></div></section>`;}
function budgetStrip(){const budget=book().budgets[state.month]||0,expense=L.summarize(book(),state.month).expense,pct=budget?expense/budget*100:0;return `<section class="panel budget-strip"><div class="budget-icon">${icon('wallet')}</div><div class="budget-info"><div class="budget-line"><strong>本月预算</strong><span>${budget?`¥${compact(expense)} <span style="color:#b5beb0">/ ¥${compact(budget)}</span>`:'给这个月定一个小目标'}</span></div><div class="budget-track"><div class="${pct>100?'over-budget':''}" style="width:${Math.max(0,Math.min(pct,100))}%"></div></div><div class="budget-meta"><span>${budget?`已使用 ${pct.toFixed(1)}%`:'尚未设置预算'}</span><span>${budget?`${expense>budget?'超支':'剩余'} ¥${fmt(Math.abs(budget-expense))}`:'设置后自动追踪'}</span></div></div><button class="icon-button" data-action="budget" aria-label="设置月度预算">${icon('chevronRight')}</button></section>`;}
const catIcon=name=>({'餐饮美食':'food','居家生活':'home','购物消费':'bag','交通出行':'car','休闲娱乐':'film','医疗健康':'heart','学习成长':'book','工资薪酬':'briefcase','兼职收入':'briefcase'})[name]||'wallet';
function filteredEntries(){return L.forMonth(book(),state.month).filter(e=>(state.filter==='all'||e.type===state.filter)&&(state.category==='all'||e.category===state.category)&&(!state.search||`${e.note} ${e.category} ${e.date}`.toLowerCase().includes(state.search.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));}
function filterTabs(){return `<div class="filter-tabs" role="group" aria-label="账单类型">${[['all','全部'],['expense','支出'],['income','收入']].map(([v,t])=>`<button data-filter="${v}" class="${state.filter===v?'active':''}" aria-pressed="${state.filter===v}">${t}</button>`).join('')}</div>`;}
function transactions(full=false){const rows=filteredEntries(),pageSize=10;const pages=Math.max(1,Math.ceil(rows.length/pageSize));state.page=Math.min(state.page,pages);const visible=full?rows.slice((state.page-1)*pageSize,state.page*pageSize):rows.slice(0,5);return `<section class="panel transactions-panel"><div class="panel-heading"><div class="panel-title"><h2>${full?'本月账单':'最近账单'}</h2><span class="tag">${L.forMonth(book(),state.month).length} 笔</span></div><div class="table-controls">${filterTabs()}${full?`<button class="text-button" data-action="export-csv">${icon('download')}导出</button>`:`<button class="text-button" data-action="transactions">全部账单${icon('arrowRight')}</button>`}</div></div>${visible.length?`<div class="table-scroll"><table><thead><tr><th>账单</th><th>分类</th><th>日期</th><th style="text-align:right">金额</th><th style="text-align:right">操作</th></tr></thead><tbody>${visible.map(e=>`<tr><td><div class="transaction-name"><span class="category-icon ${e.type}">${icon(catIcon(e.category))}</span><span>${esc(e.note||e.category)}${window.MoonFeaturesUI?.entryBadge(e)||''}</span></div></td><td><span class="tag">${esc(e.category)}</span></td><td>${e.date.replaceAll('-','/')}</td><td class="money-cell ${e.type}">${e.kind==='transfer'?'↔':e.type==='income'?'+':'−'} ${fmt(e.amount)}</td><td><div class="row-actions"><button class="icon-button" data-edit="${esc(e.id)}" aria-label="编辑 ${esc(e.note||e.category)}">${icon('edit')}</button><button class="icon-button" data-delete="${esc(e.id)}" aria-label="删除 ${esc(e.note||e.category)}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty-state">${icon('inbox')}<strong>${L.forMonth(book(),state.month).length?'没有符合条件的账单':'这个月，等你记下第一笔'}</strong><p>${L.forMonth(book(),state.month).length?'试试调整搜索或筛选条件。':'一杯咖啡、一份收入，都值得被好好记录。'}</p><button class="button primary" data-action="add">${icon('plus')}记一笔</button></div>`}<div class="table-bottom"><span>${full?`共 ${rows.length} 笔 · 支出 ¥${fmt(L.accountingEntries({entries:rows}).filter(e=>e.type==='expense').reduce((a,e)=>a+e.amount,0))}`:`显示最近 ${visible.length} 笔记录`}</span>${full&&pages>1?`<div class="pagination"><button data-page="${state.page-1}" ${state.page===1?'disabled':''} aria-label="上一页">${icon('chevronLeft')}</button>${state.page} / ${pages}<button data-page="${state.page+1}" ${state.page===pages?'disabled':''} aria-label="下一页">${icon('chevronRight')}</button></div>`:`<span>${state.mode==='demo'?'示例数据':'每一笔记录，自动保存'}</span>`}</div></section>`;}
function overview(){const s=L.summarize(book(),state.month);return stats()+`<div class="charts-grid">${trend()}${categoryChart()}</div><div class="summary-row">${budgetStrip()}<section class="panel insight-card"><span class="insight-icon">${icon('sparkles')}</span><div><h3>${s.rate===null?'从了解自己开始':s.balance>=0?'为生活留一点余地':'留意这个月的支出'}</h3><p>${s.rate===null?'记下收支，让每个月的变化慢慢变清晰。':s.balance>=0?`本月收入的 ${s.rate.toFixed(1)}% 留了下来，<br>每一点积累，都在靠近想要的生活。`:`本月支出比收入多 ¥${fmt(-s.balance)}，<br>看看哪些分类值得调整。`}</p></div></section></div>`+transactions();}
const titles={overview:['收支概览','每个月，都心中有数','看看钱从哪里来，又花在了哪里。'],transactions:['账单明细','生活的每一笔，都在这里','记录、整理，慢慢找到自己的消费节奏。'],analysis:['消费分析','让每一笔消费，更有方向','从分类和趋势中，认识自己的日常。'],budget:['月度预算','给生活，一点从容的计划','设一个合适的预算，让日常花费心中有数。']};
function render(){const title=titles[state.view];$('#breadcrumb-title').textContent=title[0];$('#page-title').innerHTML=esc(title[1])+'<span class="heading-dot">.</span>';$('#page-subtitle').textContent=title[2];$('#selected-month').value=state.month;$('#book-switch').innerHTML=(state.mode==='demo'?'示例账本':'我的账本')+icon('chevronDown');$('#demo-banner').hidden=state.mode!=='demo'&&!storageProblem;$('#demo-banner').innerHTML=storageProblem?`<span>${esc(storageProblem)}</span><button data-action="data-button">数据恢复 ${icon('arrowRight')}</button>`:`<span><span class="demo-pill">示例模式</span>先用一份示例，认识你的月度财务看板。</span><button id="start-own">开始我的账本 ${icon('arrowRight')}</button>`;$('#nav-count').textContent=L.forMonth(book(),state.month).length;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);if(b.dataset.view===state.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('#view-content').innerHTML=state.view==='overview'?overview():typeof renderSecondary==='function'?renderSecondary():overview();document.querySelectorAll('.stat-amount').forEach(el=>{if(el.textContent.length>14)el.style.fontSize='clamp(17px, 1.7vw, 25px)';});$('#previous-month').disabled=state.month==='1900-01';$('#next-month').disabled=state.month==='2100-12';if(storageProblem)$('#save-status').textContent='本地数据读取失败 · 保存已暂停';document.dispatchEvent(new CustomEvent('ledger:render'));}
hydrateIcons();
render();

function renderSecondary(){
  if(window.MoonFeaturesUI?.views[state.view])return window.MoonFeaturesUI.views[state.view]();
  if(state.view==='transactions')return `<div class="transactions-toolbar"><label class="search-input">${icon('search')}<input id="search-transactions" placeholder="搜索备注、分类或日期" aria-label="搜索账单" value="${esc(state.search)}"></label><select class="category-filter" id="category-filter" aria-label="筛选分类"><option value="all">所有分类</option>${Object.values(L.categories).flat().map(c=>`<option ${state.category===c?'selected':''}>${c}</option>`).join('')}</select></div>`+transactions(true);
  if(state.view==='analysis'){const items=L.breakdown(book(),state.month);return stats()+`<div class="charts-grid">${trend()}${categoryChart()}</div><section class="panel"><div class="panel-heading"><div><h2>钱都花在哪里了</h2><p class="panel-subtitle">按分类净支出排序 · 负数表示本月收回款项多于消费</p></div></div>${items.length?`<div class="analysis-details">${items.map(c=>`<button class="category-detail" data-category="${c.name}" style="width:100%;text-align:left"><span>${c.name}</span><span class="budget-track"><span style="display:block;height:100%;width:${c.percent}%;background:${c.color};border-radius:4px"></span></span><strong>¥${fmt(c.amount)}</strong><small>${c.percent.toFixed(1)}%</small></button>`).join('')}</div>`:`<div class="empty-state">${icon('chart')}<strong>还没有可以分析的支出</strong><p>记录后，这里会自动整理你的消费去向。</p><button class="button primary" data-action="add">记一笔</button></div>`}</section>`;}
  const budget=book().budgets[state.month]||0,expense=L.summarize(book(),state.month).expense,pct=budget?expense/budget*100:0;
  return `<div class="budget-page"><section class="panel"><div class="panel-heading"><div><h2>${monthLabel(state.month)} · 月度预算</h2><p class="panel-subtitle">预算仅统计支出，各月份独立设置。</p></div><span class="budget-icon">${icon('wallet')}</span></div><div class="budget-editor"><form id="budget-form"><label for="budget-amount">本月计划支出（元）</label><div class="budget-edit-row"><input type="number" id="budget-amount" value="${budget?(budget/100).toFixed(2):''}" placeholder="例如 8000" min="0" max="999999999.99" step="0.01" required inputmode="decimal"><button class="button primary">保存预算</button></div><p id="budget-error" class="form-error" role="alert"></p></form><div class="budget-big"><div class="budget-line"><span>本月已花</span><strong>¥${fmt(expense)}</strong></div><div class="budget-track"><div class="${pct>100?'over-budget':''}" style="width:${Math.max(0,Math.min(pct,100))}%"></div></div><div class="budget-meta"><span>${budget?`已使用 ${pct.toFixed(1)}%`:'设置预算后开始追踪'}</span><span class="${expense>budget&&budget?'danger-text':''}">${budget?`${expense>budget?'已超支':'还可支出'} ¥${fmt(Math.abs(budget-expense))}`:'预算未设置'}</span></div></div><p class="budget-tip">${pct>100?'本月支出已超过预算。可以在消费分析中查看主要花费，再决定如何安排剩余时间的开销。':'按自己的生活节奏设置预算。每记一笔支出，剩余额度都会自动更新。'}<br>填写 0 可以取消当月预算。</p></div></section></div>`;
}
function setView(view){if(!titles[view])return;state.view=view;state.filter='all';state.search='';state.category='all';state.page=1;render();window.scrollTo({top:0,behavior:'instant'});}
function setMonth(month){if(!L.validMonth(month)){toast('请选择 1900—2100 年的有效月份。');$('#selected-month').value=state.month;return;}state.month=month;state.page=1;render();}
async function setMode(mode){const previous=state.mode;state.mode=mode;if(!storageProblem&&!await persist()){state.mode=previous;return;}state.search='';state.category='all';state.filter='all';state.page=1;render();toast(mode==='own'?'已切换到我的账本，示例数据不会混入。':'已切换到示例账本');}
function populateCategories(type,selected){$('#entry-category').innerHTML=L.categories[window.MoonFeaturesUI?.entryCategoryType(type)||type].map(c=>`<option ${c===selected?'selected':''}>${c}</option>`).join('');}
let entryBase=null;
function openEntry(id){if(entrySaving)return;const entry=id?book().entries.find(e=>e.id===id):null;if(id&&!entry)return;entryBase={mode:state.mode,entry:entry?{...entry}:null};$('#entry-form').reset();$('#entry-error').textContent='';$('#entry-id').value=entry?.id||'';$('#entry-title').textContent=entry?'编辑账单':'记一笔';$('#entry-amount').value=entry?(entry.amount/100).toFixed(2):'';$('#entry-date').value=entry?.date||(state.month===L.monthNow()?L.localDate():`${state.month}-01`);$('#entry-note').value=entry?.note||'';window.MoonFeaturesUI?.populateEntry(entry);const type=entry?.type||'expense';$(`#entry-form input[value="${type}"]`).checked=true;populateCategories(type,entry?.category);$('#entry-dialog').showModal();$('#entry-amount').focus();}
function showConfirm(title,message,label,action){$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;$('#confirm-action').textContent=label;$('#confirm-action').onclick=async()=>{$('#confirm-action').disabled=true;try{const result=await action();if(result!==false)$('#confirm-dialog').close();}finally{$('#confirm-action').disabled=false;}};$('#confirm-dialog').showModal();}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function exportFallback(name,content){$('#export-fallback').hidden=false;$('#export-filename').textContent=name;$('#export-content').value=content;}
function exportJSON(){const name=`月见-${state.mode==='demo'?'示例':'我的账本'}-${L.localDate()}.json`,content=JSON.stringify({app:'moonledger',version:2,exportedAt:new Date().toISOString(),...book()},null,2);download(name,content,'application/json;charset=utf-8');exportFallback(name,content);toast('备份已生成；如果下载未开始，可使用备用保存方式。');}
function exportCSV(){const name=`月见-${state.mode==='demo'?'示例-':''}${state.month}.csv`,content=L.exportCSV(L.forMonth(book(),state.month).sort((a,b)=>b.date.localeCompare(a.date)));download(name,content,'text/csv;charset=utf-8');if(!$('#data-dialog').open)openData();exportFallback(name,content);toast('CSV 已生成；如果下载未开始，可使用备用保存方式。');}
let pendingImport=null;
function openData(){pendingImport=null;$('#export-fallback').hidden=true;$('#export-content').value='';$('#import-preview').hidden=true;$('#import-error').textContent='';$('#import-file').value='';$('#data-context').textContent=`当前是${state.mode==='demo'?'「示例账本」':'「我的账本」'}，共 ${book().entries.length} 笔账单。导入和导出只影响当前账本。`;if(storageProblem){$('#data-context').innerHTML=esc(storageProblem)+' <button class="text-button" id="export-raw">导出原始数据</button>';$('#clear-book').disabled=true;}else $('#clear-book').disabled=false;$('#data-dialog').showModal();}
function signature(entry){return JSON.stringify([entry.date,entry.type,entry.category,entry.amount,entry.note,entry.kind||'',entry.relatedId||'']);}
async function mergeImport(){if(!pendingImport)return false;if(storageProblem){$('#import-error').textContent='当前原始数据损坏，请选择完整 JSON 备份并使用替换恢复。';return false;}try{const result=window.MoonFeatures.mergeBackup(book(),pendingImport);if(await commit(result.next,`已导入 ${result.added} 笔，跳过 ${result.skipped} 笔重复记录，并合并模板与预算。`)){$('#data-dialog').close();pendingImport=null;return true;}}catch(error){$('#import-error').textContent=error.message;}return false;}
document.addEventListener('click',async event=>{
  const button=event.target.closest('button,a.brand');if(!button)return;
  if(button.classList.contains('close-dialog'))return button.closest('dialog').close();
  if(button.matches('a.brand')){event.preventDefault();return setView('overview');}
  if(button.dataset.view)return setView(button.dataset.view);
  if(button.dataset.filter){state.filter=button.dataset.filter;state.page=1;render();return;}
  if(button.dataset.edit)return openEntry(button.dataset.edit);
  if(button.dataset.delete){const entry=book().entries.find(e=>e.id===button.dataset.delete);if(!entry)return;return showConfirm('删除这笔账单？',`${entry.date} · ${entry.note||entry.category} · ¥${fmt(entry.amount)}。删除后统计将同步更新。`,'删除账单',async()=>{const mode=state.mode;const next={...book(),entries:book().entries.filter(e=>e.id!==entry.id)};if(!await commit(next,'账单已删除',{expectedEntry:entry}))return false;$('#toast').innerHTML='账单已删除 <button id="undo-delete" class="text-button" style="color:#d8edac;margin-left:14px">撤销</button>';$('#undo-delete').onclick=()=>{if(state.mode!==mode)return toast('请切回删除时的账本后再撤销。');if(!book().entries.some(e=>e.id===entry.id))commit({...book(),entries:[...book().entries,entry]},'账单已恢复');};clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),12000);return true;});}
  if(button.dataset.category){setView('transactions');state.category=button.dataset.category;state.filter='expense';render();return;}
  if(button.dataset.page){state.page=Number(button.dataset.page);render();return;}
  const action=button.dataset.action||button.id;
  if(['overview','transactions','analysis','budget'].includes(action))return setView(action);
  if(action==='add'||action==='add-button')return openEntry();
  if(action==='previous-month')return setMonth(L.shiftMonth(state.month,-1));
  if(action==='next-month')return setMonth(L.shiftMonth(state.month,1));
  if(action==='start-own')return setMode('own');
  if(action==='book-switch')return setMode(state.mode==='demo'?'own':'demo');
  if(action==='data-button')return openData();
  if(action==='copy-export'){navigator.clipboard?.writeText($('#export-content').value).then(()=>toast('文件内容已复制')).catch(()=>{$('#export-content').select();toast('请按 Ctrl+C 或 ⌘C 复制选中内容。');});if(!navigator.clipboard){$('#export-content').select();toast('请按 Ctrl+C 或 ⌘C 复制选中内容。');}return;}
  if(action==='export-json')return exportJSON();
  if(action==='export-csv')return exportCSV();
  if(action==='choose-import')return $('#import-file').click();
  if(action==='download-template'){const sample={date:`${state.month}-01`,type:'expense',category:'餐饮美食',amount:2800,note:'午餐'};download('月见-账单导入模板.csv',L.exportCSV([sample]),'text/csv;charset=utf-8');return;}
  if(action==='merge-import')return mergeImport();
  if(action==='replace-import')return showConfirm('用备份替换当前账本？',`当前账本的 ${book().entries.length} 笔记录、预算和固定模板将被替换。建议先导出完整备份。`,'确认替换',async()=>{const previousProblem=storageProblem;const recoveryRaw=storageProblem?localStorage.getItem(STORAGE):undefined;if(storageProblem){if(recoveryRaw)download('月见-恢复前原始数据.txt',recoveryRaw,'text/plain;charset=utf-8');storageProblem='';}if(await commit(pendingImport,'账本已从备份恢复',{replace:true,recoverRaw:recoveryRaw})){$('#data-dialog').close();pendingImport=null;return true;}storageProblem=previousProblem;return false;});
  if(action==='clear-book')return showConfirm('清空当前账本？',`将清除${state.mode==='demo'?'示例账本':'我的账本'}的 ${book().entries.length} 笔账单、所有预算和固定模板。此操作无法直接撤销，请先导出备份。`,'确认清空',async()=>{if(await commit({entries:[],budgets:{}},'当前账本已清空',{replace:true})){$('#data-dialog').close();return true;}return false;});
  if(action==='export-raw'){const raw=localStorage.getItem(STORAGE);if(raw)download('月见-原始数据恢复.txt',raw,'text/plain;charset=utf-8');return;}
});
document.addEventListener('change',event=>{
  if(event.target.id==='selected-month')setMonth(event.target.value);
  if(event.target.name==='type')populateCategories(event.target.value);
  if(event.target.id==='category-filter'){state.category=event.target.value;state.page=1;render();}
});
document.addEventListener('input',event=>{if(event.target.id==='search-transactions'){state.search=event.target.value;state.page=1;const start=event.target.selectionStart,end=event.target.selectionEnd;render();$('#search-transactions').focus();$('#search-transactions').setSelectionRange(start,end);}});
let entrySaving=false;
$('#entry-form').addEventListener('submit',async event=>{event.preventDefault();if(entrySaving)return;entrySaving=true;$('#entry-form button[type="submit"]').disabled=true;try{if(state.mode!==entryBase?.mode)throw Error('账本已切换，请重新打开记账表单。');const id=$('#entry-id').value,type=$('#entry-form input[name="type"]:checked').value;const entry=L.validateEntry({...entryBase.entry,...(window.MoonFeaturesUI?.entryExtras()||{}),id:id||L.uid(),type,amount:L.cents($('#entry-amount').value),date:$('#entry-date').value,category:$('#entry-category').value,note:$('#entry-note').value.trim()});const entries=id?book().entries.map(e=>e.id===id?entry:e):[...book().entries,entry];if(await commit({...book(),entries},id?'账单已更新':'记好了，生活又清晰了一点。',{expectedEntry:entryBase.entry})){$('#entry-dialog').close();state.month=entry.date.slice(0,7);render();}}catch(e){$('#entry-error').textContent=e.message;}finally{entrySaving=false;$('#entry-form button[type="submit"]').disabled=false;}});
document.addEventListener('submit',async event=>{if(event.target.id!=='budget-form')return;event.preventDefault();try{const raw=$('#budget-amount').value;const amount=Number(raw)===0?0:L.cents(raw);const budgets={...book().budgets};if(amount)budgets[state.month]=amount;else delete budgets[state.month];commit({...book(),budgets},amount?'本月预算已保存':'本月预算已取消');}catch(e){$('#budget-error').textContent=e.message;}});
$('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;if(!/\.json$/i.test(file.name)&&window.MoonFeaturesUI){window.MoonFeaturesUI.openImport();await window.MoonFeaturesUI.handleImportFile(file);return;}pendingImport=null;$('#import-error').textContent='';$('#import-preview').hidden=true;try{if(file.size>10*1024*1024)throw Error('文件过大，请选择 10 MB 以内的备份。');const content=await file.text();const isJSON=/\.json$/i.test(file.name);if(!isJSON&&!/\.csv$/i.test(file.name))throw Error('请选择 JSON 或 CSV 文件。');if(isJSON){const raw=JSON.parse(content);if(raw.app!=='moonledger'||![1,2].includes(raw.version))throw Error('不是受支持的月见备份。');pendingImport=L.validateBook(raw);}else pendingImport={entries:L.importCSV(content),budgets:{}};if(!pendingImport.entries.length&&!Object.keys(pendingImport.budgets).length&&!Object.keys(pendingImport.categoryBudgets||{}).length&&!pendingImport.recurring?.length&&!pendingImport.ignoredDuplicates?.length)throw Error('文件中没有可导入的账单或预算。');$('#import-preview').innerHTML=`<strong>读取成功 · ${pendingImport.entries.length} 笔账单 · ${(pendingImport.recurring||[]).length} 个固定模板${isJSON?`，${Object.keys(pendingImport.budgets).length} 个月预算`:''}</strong><p>合并时跳过相同账单，合并固定模板与分类预算；同名编号的已有设置优先。</p><button class="button primary" id="merge-import">合并导入</button>${isJSON?'<button class="button secondary" id="replace-import">替换当前账本</button>':''}`;$('#import-preview').hidden=false;}catch(e){pendingImport=null;$('#import-error').textContent=e instanceof SyntaxError?'JSON 文件格式不正确，请使用完整备份文件。':e.message;}finally{event.target.value='';}});
window.addEventListener('storage',event=>{if(event.key!==STORAGE)return;try{if(!event.newValue){storageProblem='本地账本已在另一个页面移除。请先导出当前账本，然后刷新。';toast(storageProblem);return;}const next=JSON.parse(event.newValue);if(![1,2].includes(next.version))throw Error('版本错误');state.own=L.validateBook(next.own);state.demo=L.validateBook(next.demo);render();toast('账本已与另一个页面同步');}catch(e){storageProblem='检测到无效的外部账本数据，已暂停保存。请先导出备份。';toast(storageProblem);}});
// Optional browser-agent integration uses exactly the same month selector and state.
if(document.modelContext?.registerTool){const controller=new AbortController();const tools=[{name:'get_monthly_summary',title:'读取月度收支',description:'Read income, expense, balance and budget for a calendar month in the currently selected ledger. Does not change data.',inputSchema:{type:'object',properties:{month:{type:'string',description:'YYYY-MM'}},required:['month'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!L.validMonth(input?.month))throw Error('Invalid month. Use YYYY-MM within 1900–2100.');return{mode:state.mode,month:input.month,currency:'CNY',unit:'cents',...L.summarize(book(),input.month),budget:book().budgets[input.month]||null};}},{name:'navigate_to_month',title:'查看指定月份',description:'Navigate the visible dashboard to a calendar month without modifying ledger records.',inputSchema:{type:'object',properties:{month:{type:'string'}},required:['month'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!L.validMonth(input?.month))throw Error('Invalid month. Use YYYY-MM within 1900–2100.');setMonth(input.month);return{month:state.month,view:state.view};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch(e){/* Feature support is optional; the visible interface remains available. */}}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
